// Day-7 review S2: proofs/refusals/INDEX.md is generated by tests/tools/refusal-index.ts from the files in
// this repo. This test fails when the committed index differs from the script's output (a new run file,
// a new refusal record, or a hand edit), and pins the facts the review checked by hand.

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { buildRefusalIndex, collect, INDEX_PATH } from "../tools/refusal-index";

describe("S2: the refusal index is generated from the files and cannot drift", () => {
  const data = collect();
  it("the committed INDEX.md equals the script's output (run `pnpm tsx tests/tools/refusal-index.ts --write` to update)", () => {
    expect(readFileSync(INDEX_PATH, "utf8")).toBe(buildRefusalIndex(data));
  });
  it("D07-01's Spark Open declines are in it: cu96dAM4Bf (Spark Open) and ytshhYe28r (Spark and Spark Open)", () => {
    const r = (run: string) => data.rows.filter((x) => x.runId === run).map((x) => x.bettor).sort();
    expect(r("cu96dAM4Bf")).toEqual(["Muse Spark Open (meta-models/muse-spark-open-1026) · via Baseten"]);
    expect(r("ytshhYe28r")).toEqual(["Muse Spark 1.3 (muse-spark-1.3)", "Muse Spark Open (meta-models/muse-spark-open-1026) · via Baseten"]);
    // E5 review r1 (M5): 22 since the E5 live run in Muse Code, where Muse Spark 1.3 declined "what does it return"
    // (run Ehs2a0hAe8, tests/evidence/E5/live/proof-Ehs2a0hAe8.atlas.json).
    expect(r("Ehs2a0hAe8")).toEqual(["Muse Spark 1.3 (muse-spark-1.3)"]);
    expect(data.rows).toHaveLength(22);
  });
  it("a network failure is not a decline: round 4's Spark slot is under 'not counted', never a row", () => {
    expect(data.rows.some((x) => x.runId === "cu96dAM4Bf" && x.bettor.startsWith("Muse Spark 1.3"))).toBe(false);
    expect(data.slots.some((s) => s.runId === "cu96dAM4Bf" && s.model === "muse-spark-1.3" && /network error/.test(s.reason))).toBe(true);
    expect(buildRefusalIndex(data)).toContain("tests/evidence/D01-review/probes-after.txt");
  });
  it("every row's files exist and every row is a judge verdict or a named plain-text source", () => {
    for (const r of data.rows) {
      expect(r.files.size).toBeGreaterThan(0);
      expect(r.reason.length).toBeGreaterThan(0);
    }
  });
});
